package com.betterbosshealthbar;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum BarStyle {
    OLD_SCHOOL("Old School"), RUNESCAPE_3("Runescape 3");

    private final String name;

    @Override
    public String toString() {
        return name;
    }
}

package com.betterbosshealthbar;

import java.awt.Color;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BetterBossHealthBarConfig.GROUP)
public interface BetterBossHealthBarConfig extends Config {
    String GROUP = "betterbosshealthbar";
    String BREAKPOINTS_KEY = "breakpoints";

    @ConfigSection(
            name = "Health Bar",
            description = "Size and color of the health bar.",
            position = 10
    )
    String healthbarSection = "healthbar";

    @ConfigSection(
            name = "Text",
            description = "Size and colors of rendered text.",
            position = 20
    )
    String textSection = "text";

    @ConfigSection(
            name = "Animation",
            description = "Interpolation, damage buffer and hit flash",
            position = 30
    )
    String animationSection = "animation";

    @ConfigSection(
            name = "Breakpoints",
            description = "Per-boss percentage breakpoints",
            position = 40
    )
    String breakpointSection = "breakpoints";

    // Preview Toggle
    @ConfigItem(
            keyName = "preview",
            name = "Preview",
            description = "Enable a persistent preview when customizing your bar in safe areas.",
            position = 0
    )
    default boolean preview() {
        return false;
    }

    // Health Bar Section
    @ConfigItem(
            keyName = "style",
            name = "Style",
            description = "Old School: flat bar with breakpoints split into separate segments.<br>"
                    + "Modern: rounded, shaded bar with breakpoints shown as notches.",
            position = 0,
            section = healthbarSection
    )
    default BarStyle style() {
        return BarStyle.OLD_SCHOOL;
    }

    @ConfigItem(
            keyName = "hpDisplay",
            name = "HP Display",
            description = "How the boss's hitpoints are shown inside the bar",
            position = 1,
            section = healthbarSection
    )
    default HpDisplay hpDisplay() {
        return HpDisplay.PERCENT;
    }

    @Range(max = 1000)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "barWidth",
            name = "Width",
            description = "Width of the bar.",
            position = 2,
            section = healthbarSection
    )
    default int barWidth() {
        return 240;
    }

    @Range(min = 2, max = 40)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "barHeight",
            name = "Height",
            description = "Height of the bar.",
            position = 3,
            section = healthbarSection
    )
    default int barHeight() {
        return 12;
    }

    @ConfigItem(
            keyName = "healthColor",
            name = "Health Color",
            description = "Color of the remaining health",
            position = 4,
            section = healthbarSection
    )
    default Color healthColor() {
        return new Color(0, 146, 54);
    }

    @Alpha
    @ConfigItem(
            keyName = "backgroundColor",
            name = "Background Color",
            description = "Color of the missing health",
            position = 5,
            section = healthbarSection
    )
    default Color backgroundColor() {
        return new Color(120, 18, 18);
    }

    @Range(max = 4)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "borderWidth",
            name = "Border Width",
            description = "Thickness of the border. 0 disables the border.",
            position = 6,
            section = healthbarSection
    )
    default int borderWidth() {
        return 1;
    }

    @Alpha
    @ConfigItem(
            keyName = "borderColor",
            name = "Border Color",
            description = "Color of the border and the breakpoint notches",
            position = 7,
            section = healthbarSection
    )
    default Color borderColor() {
        return Color.BLACK;
    }

    // Text Section
    @Range(max = 32)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "nameSize",
            name = "Name Size",
            description = "Font size of the boss name above the bar.",
            position = 0,
            section = textSection
    )
    default int nameSize() {
        return 16;
    }

    @ConfigItem(
            keyName = "nameColor",
            name = "Name Color",
            description = "Color of the boss name",
            position = 1,
            section = textSection
    )
    default Color nameColor() {
        return new Color(230, 180, 40);
    }

    @Range(max = 3)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "nameShadowOffset",
            name = "Name Shadow Offset",
            description = "How many pixels to offset the shadow on the boss name.",
            position = 2,
            section = textSection
    )
    default int nameShadowOffset() {
        return 1;
    }

    @ConfigItem(
            keyName = "nameShadowColor",
            name = "Name Shadow Color",
            description = "Color of the text shadow on the boss name.",
            position = 3,
            section = textSection
    )
    default Color nameShadowColor() {
        return Color.BLACK;
    }

    @Range(max = 32)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "hpSize",
            name = "HP Size",
            description = "Font size of the HP text inside the bar.",
            position = 4,
            section = textSection
    )
    default int hpSize() {
        return 16;
    }

    @ConfigItem(
            keyName = "hpTextColor",
            name = "HP Color",
            description = "Color of the HP text inside the bar",
            position = 5,
            section = textSection
    )
    default Color hpTextColor() {
        return Color.WHITE;
    }

    @Range(max = 3)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "hpShadowOffset",
            name = "HP Shadow Offset",
            description = "How many pixels to offset the shadow on the hp text.",
            position = 6,
            section = textSection
    )
    default int hpShadowOffset() {
        return 1;
    }

    @ConfigItem(
            keyName = "hpShadowColor",
            name = "HP Shadow Color",
            description = "Color of the text shadow on the hp text.",
            position = 7,
            section = textSection
    )
    default Color hpShadowColor() {
        return Color.BLACK;
    }

    // Animation Section
    @Range(max = 50)
    @ConfigItem(
            keyName = "interpolationSpeed",
            name = "Interpolation Speed",
            description = "How quickly the health slides to its new value. Higher is faster.",
            position = 0,
            section = animationSection
    )
    default int interpolationSpeed() {
        return 12;
    }

    @Range(max = 50)
    @ConfigItem(
            keyName = "bufferSpeed",
            name = "Buffer Drain Speed",
            description = "How quickly the buffer drains once its delay ends. Higher is faster. 0 snaps instantly.",
            position = 1,
            section = animationSection
    )
    default int bufferSpeed() {
        return 6;
    }

    @Range(max = 20)
    @Units(Units.TICKS)
    @ConfigItem(
            keyName = "bufferDelay",
            name = "Buffer Delay",
            description = "Game ticks the damage buffer waits after the last hit before draining.",
            position = 2,
            section = animationSection
    )
    default int bufferDelay() {
        return 2;
    }


    @Alpha
    @ConfigItem(
            keyName = "bufferColor",
            name = "Buffer Color",
            description = "Color of the recent damage that has not drained yet",
            position = 3,
            section = animationSection
    )
    default Color bufferColor() {
        return new Color(230, 180, 40);
    }

    @Range(max = 2000)
    @Units(Units.MILLISECONDS)
    @ConfigItem(
            keyName = "hitFlashDuration",
            name = "Hit Flash Duration",
            description = "How long the bar flashes when the boss takes damage.",
            position = 4,
            section = animationSection
    )
    default int hitFlashDuration() {
        return 200;
    }

    @Alpha
    @ConfigItem(
            keyName = "hitFlashColor",
            name = "Hit Flash Color",
            description = "Color the bar flashes when the boss takes damage",
            position = 5,
            section = animationSection
    )
    default Color hitFlashColor() {
        return new Color(255, 255, 255, 170);
    }

    // Breakpoint Section
    @Range(max = 10)
    @Units(Units.PIXELS)
    @ConfigItem(
            keyName = "breakpointSize",
            name = "Breakpoint Size",
            description = "Width of each breakpoint.",
            position = 0,
            section = breakpointSection
    )
    default int breakpointSize() {
        return 2;
    }

    @ConfigItem(
            keyName = BREAKPOINTS_KEY,
            name = "Boss Breakpoints",
            description = "One boss per line: the boss name, a colon, then percentages separated by commas.<br>"
                    + "Example: Alchemical Hydra: 75, 50, 25<br>"
                    + "Names are not case sensitive. Lines starting with # are ignored.",
            position = 1,
            section = breakpointSection
    )
    default String breakpoints() {
        return "";
    }
}

package com.betterbosshealthbar;

import java.awt.*;
import java.awt.geom.Area;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;

import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class BetterBossHealthBarOverlay extends Overlay {
    private static final int NAME_GAP = 2;
    private static final float[] GRADIENT_STOPS = {0f, 0.5f, 1f};
    private static final Color GLOSS_TOP = new Color(255, 255, 255, 80);
    private static final Color GLOSS_BOTTOM = new Color(255, 255, 255, 0);

    private final BetterBossHealthBarPlugin plugin;
    private final BetterBossHealthBarConfig config;

    private Font nameFont;
    private int nameFontSize = -1;
    private Font hpFont;
    private int hpFontSize = -1;

    private String hpText;
    private HpDisplay hpTextDisplay;
    private int hpTextCurrent = -1;
    private int hpTextMax = -1;

    @Inject
    BetterBossHealthBarOverlay(BetterBossHealthBarPlugin plugin, BetterBossHealthBarConfig config) {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGHEST);
        setMovable(true);
        setResettable(true);
    }

    /**
     * Centers the bar on the game's health bar, unless the user has moved it.
     */
    void anchorTo(Rectangle gameBar) {
        if (getPreferredLocation() == null) {
            getBounds().setLocation(gameBar.x + (gameBar.width - config.barWidth()) / 2, gameBar.y);
        }
    }

    @Override
    public OverlayPosition getPreferredPosition() {
        OverlayPosition position = super.getPreferredPosition();
        return position != null ? position : OverlayPosition.TOP_CENTER;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        HealthBarState state = plugin.getState();
        if (!state.isActive() && !state.isVisible() && !config.preview()) {
            return null;
        }

        long now = System.nanoTime();
        if (!config.preview()) {
            state.animate(now, plugin.getTickCount(), config.interpolationSpeed(), config.bufferSpeed(), config.bufferDelay());
        }

        int width = config.barWidth();
        int border = config.borderWidth();
        int barHeight = config.barHeight();
        int outerHeight = barHeight + border * 2;

        Graphics2D g = (Graphics2D) graphics.create();

        // Apply opaque transparency layer over the entire health bar, based on the visibility value.
        if (config.preview()) {
            g.setComposite(AlphaComposite.SrcOver.derive(1f));
        } else {
            g.setComposite(AlphaComposite.SrcOver.derive((float) state.getVisibility()));
        }

        try {

            if (config.style() == BarStyle.RUNESCAPE_3) {
                g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            } else {
                // RuneScape fonts are bitmap-style; keep them crisp
                g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
            }

            String name = state.getName();
            int barY = 0;
            if (config.nameSize() > 0 && !name.isEmpty()) {
                g.setFont(getNameFont(config.nameSize()));
                FontMetrics fm = g.getFontMetrics();
                int x = (width - fm.stringWidth(name)) / 2;
                drawText(g, name, x, fm.getAscent(), config.nameColor(), config.nameShadowOffset(), config.nameShadowColor());
                barY = fm.getAscent() + NAME_GAP;
            }

            float[] breakpoints = config.breakpointSize() > 0 ? plugin.getBreakpoints(name) : Breakpoints.NONE;
            if (config.preview()) {
                breakpoints = new float[]{0.33f, 0.66f};
            }

            float flash = state.flashAlpha(now, config.hitFlashDuration());
            Color flashColor = flash > 0 ? scaleAlpha(config.hitFlashColor(), flash) : null;

            if (config.style() == BarStyle.RUNESCAPE_3) {
                drawRunescape3(g, barY, width, outerHeight, border, breakpoints, state.getFill(), state.getBuffer(), flashColor);
            } else {
                drawOldSchool(g, barY, width, outerHeight, border, breakpoints, state.getFill(), state.getBuffer(), flashColor);
            }

            drawHpText(g, state, barY + (int) Math.round(barHeight / 16.0), width, outerHeight);

            return new Dimension(width, barY + outerHeight);
        } finally {
            g.dispose();
        }
    }

    // Basic rectangular health bar designed after the health bar found in the Theatre of Blood.
    private void drawOldSchool(Graphics2D g, int y, int width, int height, int border, float[] breakpoints, double fill, double buffer, Color flashColor) {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

        // Fill positions are measured across the whole bar, then clipped to each segment
        int innerLeft = border;
        int innerWidth = width - border * 2;
        int fillEnd = innerLeft + (int) Math.round(innerWidth * fill);
        int bufferEnd = innerLeft + (int) Math.round(innerWidth * buffer);
        int gap = config.breakpointSize();

        int segmentStart = 0;
        for (int i = 0; i <= breakpoints.length; i++) {
            int segmentEnd;
            int nextStart;
            if (i < breakpoints.length) {
                int split = innerLeft + Math.round(innerWidth * breakpoints[i]);
                segmentEnd = split - gap / 2;
                nextStart = segmentEnd + gap;
            } else {
                segmentEnd = width;
                nextStart = width;
            }

            if (segmentEnd - segmentStart > border * 2) {
                drawSegment(g, segmentStart, y, segmentEnd - segmentStart, height, border, fillEnd, bufferEnd, flashColor);
            }
            segmentStart = nextStart;
        }
    }

    private void drawSegment(Graphics2D g, int x, int y, int w, int h, int border, int fillEnd, int bufferEnd, Color flashColor) {
        if (border > 0) {
            g.setColor(config.borderColor());
            g.fillRect(x, y, w, border);
            g.fillRect(x, y + h - border, w, border);
            g.fillRect(x, y + border, border, h - border * 2);
            g.fillRect(x + w - border, y + border, border, h - border * 2);
        }

        int left = x + border;
        int right = x + w - border;
        int top = y + border;
        int innerHeight = h - border * 2;

        g.setColor(config.backgroundColor());
        g.fillRect(left, top, right - left, innerHeight);

        fillSpan(g, config.bufferColor(), fillEnd, bufferEnd, left, right, top, innerHeight);
        fillSpan(g, config.healthColor(), left, fillEnd, left, right, top, innerHeight);

        if (flashColor != null) {
            fillSpan(g, flashColor, left, bufferEnd, left, right, top, innerHeight);
        }
    }

    /**
     * Fills the horizontal span [from, to) limited to [minX, maxX).
     */
    private static void fillSpan(Graphics2D g, Color color, int from, int to, int minX, int maxX, int y, int h) {
        int start = Math.max(from, minX);
        int end = Math.min(to, maxX);
        if (end > start) {
            g.setColor(color);
            g.fillRect(start, y, end - start, h);
        }
    }

    private void drawRS3Segment(Graphics2D g, float x, float y, float w, float h, float border, float fillEnd, float bufferEnd, Color flashColor) {
        float innerX = x + border;
        float innerY = y + border;
        float innerWidth = w - border * 2;
        float innerHeight = h - border * 2;
        float bottom = innerY + innerHeight;
        float innerRight = innerX + innerWidth;

        Shape inner = new RoundRectangle2D.Float(innerX, innerY, innerWidth, innerHeight, innerHeight / 1.5f, innerHeight / 1.5f);

        if (border > 0) {
            Area frame = new Area(new RoundRectangle2D.Float(x, y, w, h, h / 1.5f, h / 1.5f));
            frame.subtract(new Area(inner));
            g.setColor(config.borderColor());
            g.fill(frame);
        }

        Color background = config.backgroundColor();
        fillLayer(g, inner, bufferEnd, innerRight, innerY, innerHeight, new GradientPaint(0, innerY, darken(background, 0.55f), 0, bottom, background));
        fillLayer(g, inner, fillEnd, bufferEnd, innerY, innerHeight, bevel(config.bufferColor(), innerY, bottom));
        fillLayer(g, inner, innerX, fillEnd, innerY, innerHeight, bevel(config.healthColor(), innerY, bottom));

        fillLayer(g, inner, innerX, innerRight, innerY, innerHeight / 2, new GradientPaint(0, innerY, GLOSS_TOP, 0, innerY + innerHeight / 2, GLOSS_BOTTOM));

        if (flashColor != null) {
            fillLayer(g, inner, innerX, bufferEnd, innerY, innerHeight, flashColor);
        }
    }


    // A more modern looking health bar with gradient shading and slightly rounder shape. Renders a more modern font.
    private void drawRunescape3(Graphics2D g, int y, int width, int height, int border, float[] breakpoints, double fill, double buffer, Color flashColor) {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        float innerX = border;
        float innerWidth = width - border * 2;

        float fillEnd = innerX + (float) (innerWidth * fill);
        float bufferEnd = innerX + (float) (innerWidth * buffer);

        int gap = config.breakpointSize();
        float segmentStart = 0;
        for (int i = 0; i <= breakpoints.length; i++) {
            float segmentEnd;
            float nextStart;
            if (i < breakpoints.length) {
                float split = innerX + innerWidth * breakpoints[i];
                segmentEnd = split - gap / 2f;
                nextStart = segmentEnd + gap;
            } else {
                segmentEnd = width;
                nextStart = width;
            }

            if (segmentEnd - segmentStart > border * 2) {
                drawRS3Segment(g, segmentStart, y, segmentEnd - segmentStart, height, border, fillEnd, bufferEnd, flashColor);
            }
            segmentStart = nextStart;
        }
    }

    /**
     * Fills the part of the bar shape within the horizontal span [from, to) and the given rows.
     */
    private static void fillLayer(Graphics2D g, Shape bar, float from, float to, float y, float h, Paint paint) {
        if (to <= from) {
            return;
        }
        Area layer = new Area(bar);
        layer.intersect(new Area(new Rectangle2D.Float(from, y, to - from, h)));
        g.setPaint(paint);
        g.fill(layer);
    }

    private void drawHpText(Graphics2D g, HealthBarState state, int barY, int width, int barHeight) {
        HpDisplay display = config.hpDisplay();
        int size = config.hpSize();

        if (display == HpDisplay.NONE || size <= 0) {
            return;
        }

        String text = getHpText(display, state.getCurrentHp(), state.getMaxHp());
        g.setFont(getHpFont(size));
        FontMetrics fm = g.getFontMetrics();
        int x = (width - fm.stringWidth(text)) / 2;
        int y = barY + (barHeight + fm.getAscent() - fm.getDescent()) / 2;
        drawText(g, text, x, y, config.hpTextColor(), config.hpShadowOffset(), config.hpShadowColor());
    }

    private String getHpText(HpDisplay display, int current, int max) {
        if (display != hpTextDisplay || current != hpTextCurrent || max != hpTextMax) {
            hpTextDisplay = display;
            hpTextCurrent = current;
            hpTextMax = max;

            String percent = String.format("%.1f%%", current * 100.0 / max);
            String value = current + " / " + max;
            switch (display) {
                case HITPOINTS:
                    hpText = value;
                    break;
                case BOTH:
                    hpText = value + " (" + percent + ")";
                    break;
                default:
                    hpText = percent;
                    break;
            }
        }
        return hpText;
    }

    private Font getNameFont(int size) {
        Font desiredFont = config.style() == BarStyle.RUNESCAPE_3 ? plugin.getRs3Font() : FontManager.getRunescapeFont();
        if (size != nameFontSize || desiredFont != nameFont) {
            nameFontSize = size;
            nameFont = desiredFont.deriveFont((float) size);
        }
        return nameFont;
    }

    private Font getHpFont(int size) {
        if (size != hpFontSize) {
            hpFontSize = size;
            hpFont = FontManager.getRunescapeSmallFont().deriveFont((float) size);
        }
        return hpFont;
    }

    private void drawText(Graphics2D g, String text, int x, int y, Color color, int shadowOffset, Color shadowColor) {
        if (shadowOffset != 0) {
            g.setColor(shadowColor);
            g.drawString(text, x + shadowOffset, y + shadowOffset);
        }

        g.setColor(color);
        g.drawString(text, x, y);
    }

    /**
     * Vertical light-to-dark gradient that makes a flat color look rounded.
     */
    private static LinearGradientPaint bevel(Color color, float top, float bottom) {
        return new LinearGradientPaint(0, top, 0, bottom, GRADIENT_STOPS, new Color[]{lighten(color, 0.35f), color, darken(color, 0.6f)});
    }

    private static Color lighten(Color c, float amount) {
        return new Color(c.getRed() + Math.round((255 - c.getRed()) * amount), c.getGreen() + Math.round((255 - c.getGreen()) * amount), c.getBlue() + Math.round((255 - c.getBlue()) * amount), c.getAlpha());
    }

    private static Color darken(Color c, float factor) {
        return new Color(Math.round(c.getRed() * factor), Math.round(c.getGreen() * factor), Math.round(c.getBlue() * factor), c.getAlpha());
    }

    private static Color scaleAlpha(Color c, float factor) {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.round(c.getAlpha() * factor));
    }
}

package com.betterbosshealthbar;

import com.google.inject.Provides;

import java.awt.*;
import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import javax.inject.Inject;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
        name = "Better Boss Health Bar",
        description = "Replaces the default boss health bar with a dynamic and customizable one.",
        tags = {"boss", "health", "healthbar", "hitpoints", "hp", "bar", "hud", "overlay", "pvm", "better", "ui", "combat", "theme"}
)
public class BetterBossHealthBarPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BetterBossHealthBarOverlay overlay;

    @Inject
    private BetterBossHealthBarConfig config;

    @Getter(AccessLevel.PACKAGE)
    private final HealthBarState state = new HealthBarState();

    /**
     * Game tick counter used to time the damage buffer delay.
     */
    @Getter(AccessLevel.PACKAGE)
    private int tickCount;

    private boolean collapsed;

    private Map<String, float[]> breakpoints = Collections.emptyMap();
    private String breakpointsName;
    private float[] breakpointsForName = Breakpoints.NONE;

    @Getter
    private Font rs3Font;
    @Getter
    private Font rs3SmallFont;

    private int lastBossVarbit = -1;

    private static final Map<String, Integer> EXTRA_BOSSES = Map.of(
            "zulrah", 500,
            "giant mole", 200,
            "corporeal beast", 2000
    );
    private static final int GRACE_TICKS = 12;
    private static final int NEARBY_DISTANCE = 20; // tiles

    private final Set<NPC> nearbyBosses = new HashSet<>();
    private final Map<String, Integer> lastKnownHp = new HashMap<>();
    private int extraSeenTick = -1000;

    // Store the dimensions of the original boss bar to restore it later.
    private int originalWidth = -1;
    private int originalHeight = -1;

    @Override
    protected void startUp() {
        // Load RS3-style font
        try (InputStream is = getClass().getResourceAsStream("/fonts/Cinzel-Bold.ttf")) {
            rs3Font = Font.createFont(Font.TRUETYPE_FONT, is).deriveFont(16f);
            GraphicsEnvironment.getLocalGraphicsEnvironment().registerFont(rs3Font);
        } catch (IOException | FontFormatException e) {
            log.error("Failed to load RS3 font", e);
        }

        try (InputStream is = getClass().getResourceAsStream("/fonts/NotoSans-Regular.ttf")) {
            rs3SmallFont = Font.createFont(Font.TRUETYPE_FONT, is).deriveFont(16f);
            GraphicsEnvironment.getLocalGraphicsEnvironment().registerFont(rs3SmallFont);
        } catch (IOException | FontFormatException e) {
            log.error("Failed to load RS3 font", e);
        }

        loadBreakpoints();
        overlayManager.add(overlay);

        // If any white listed bosses are nearby on start, add them to the list.
        clientThread.invoke(() -> {
            for (NPC npc : client.getNpcs()) {
                if (isWhitelisted(npc)) {
                    nearbyBosses.add(npc);
                }
            }
        });
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(overlay);
        state.reset();
        clientThread.invoke(this::restoreGameBar);

        // Free up the font references
        rs3Font = null;
        rs3SmallFont = null;

        // Remove any references to bosses on shutdown.
        nearbyBosses.clear();
        lastKnownHp.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (BetterBossHealthBarConfig.GROUP.equals(event.getGroup())
                && BetterBossHealthBarConfig.BREAKPOINTS_KEY.equals(event.getKey())) {
            loadBreakpoints();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        tickCount++;
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        if (config.preview()) {
            state.update("Yama", 750, 1500, 0, 0, 0);
            state.previewBuffer();
            return;
        }

        String name;
        int current;
        int max;

        Widget hp = getGameBar();
        if (hp != null) {
            // The game is showing it's own bar, use it.
            name = readBossName();
            current = client.getVarbitValue(VarbitID.HPBAR_HUD_HP);
            max = client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP);
        } else {
            NPC npc = getNearestBoss();
            if (npc == null) {
                // No whitelisted boss in range. Keep the bar for a few ticks, then fade out.
                if (tickCount - extraSeenTick > GRACE_TICKS) {
                    state.deactivate();
                }
                return;
            }

            extraSeenTick = tickCount;

            name = Text.removeTags(npc.getName());
            max = EXTRA_BOSSES.get(name.toLowerCase(Locale.ROOT));

            if (npc.isDead()) {
                current = 0;
                lastKnownHp.remove(name); // a respawn starts at full health
            } else if (npc.getHealthScale() > 0 && npc.getHealthRatio() >= 0) {
                current = (int) Math.ceil(npc.getHealthRatio() * max / (double) npc.getHealthScale());
                lastKnownHp.put(name, current);
            } else {
                // Use last know hp, if it exists. Otherwise, assume it's full.
                current = lastKnownHp.getOrDefault(name, max);
            }
        }

        state.update(name, current, max, tickCount, System.nanoTime(), config.bufferDelay());
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired event) {
        // Give the game's update script the bar exactly as the game left it, so the
        // script decides which pieces should be visible
        if (event.getScriptId() == ScriptID.HP_HUD_UPDATE) {
            restoreGameBar();
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == ScriptID.HP_HUD_UPDATE) {
            updateGameBar();
        }
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event) {
        // The game's scripts may unhide pieces at any time, so update them again every frame
        updateGameBar();
    }

    /**
     * @return the game's health bar while it is showing a bar this plugin replaces, otherwise null
     */
    private Widget getGameBar() {
        Widget hp = client.getWidget(InterfaceID.HpbarHud.HP);

        // We no longer explicitly hide widgets, but I will leave this check here... out of fear of breaking something...
        if (hp == null || hp.isHidden() || client.getVarbitValue(VarbitID.HPBAR_HUD_BASEHP) <= 0) {
            return null;
        }

        int bossVarbit = client.getVarbitValue(VarbitID.HPBAR_HUD_BOSS);
        if (bossVarbit != lastBossVarbit) {
            lastBossVarbit = bossVarbit;
            log.debug("HP hud boss varbit {} (npc {})", bossVarbit, client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC));
        }
        return bossVarbit == 1 ? hp : null;
    }

    // Helper function for collapsing the health widget
    private void collapse(Widget hp) {
        if (collapsed && hp.getOriginalWidth() == 0 && hp.getOriginalHeight() == 0) {
            return;
        }

        if (!collapsed) {
            originalWidth = hp.getOriginalWidth();
            originalHeight = hp.getOriginalHeight();
        }

        hp.setOriginalWidth(0);
        hp.setOriginalHeight(0);
        hp.revalidate();

        collapsed = true;
    }


    /**
     * Hides the game's health bar while it is showing a bar this plugin replaces, and hands
     * it back untouched otherwise.
     *
     * @return the game's health bar if it is being replaced, otherwise null
     */
    private Widget updateGameBar() {
        Widget hp = getGameBar();
        if (hp == null) {
            restoreGameBar();
            return null;
        }

        collapse(hp);
        return hp;
    }

    /**
     * @return breakpoint fractions (ascending, 0-1) configured for the given boss
     */
    float[] getBreakpoints(String name) {
        if (!name.equals(breakpointsName)) {
            breakpointsName = name;
            breakpointsForName = breakpoints.getOrDefault(Breakpoints.normalizeName(name), Breakpoints.NONE);
        }
        return breakpointsForName;
    }

    private void loadBreakpoints() {
        breakpoints = Breakpoints.parse(config.breakpoints());
        breakpointsName = null;
    }

    private String readBossName() {
        int npcId = client.getVarpValue(VarPlayerID.HPBAR_HUD_NPC);
        if (npcId > 0) {
            NPCComposition npc = client.getNpcDefinition(npcId);
            if (npc != null && npc.getName() != null) {
                return Text.removeTags(npc.getName());
            }
        }

        Widget nameWidget = client.getWidget(InterfaceID.HpbarHud.CREATURE_NAME);
        if (nameWidget != null) {
            String text = nameWidget.getText();
            if (text != null && !text.isEmpty()) {
                return Text.removeTags(text);
            }
        }

        return "";
    }

    private void restoreGameBar() {
        // Simplified handling of health bar, removing the complicated hidden children managment system.
        if (!collapsed) {
            return;
        }

        Widget hp = client.getWidget(InterfaceID.HpbarHud.HP);
        if (hp != null) {
            hp.setOriginalWidth(originalWidth);
            hp.setOriginalHeight(originalHeight);
            hp.revalidate();
        }

        collapsed = false;
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event) {
        NPC npc = event.getNpc();
        if (isWhitelisted(npc)) {
            nearbyBosses.add(npc);
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        nearbyBosses.remove(event.getNpc());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        // NPCs that left are removed by despawn events, so only clear on a full reset
        if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN) {
            nearbyBosses.clear();
            lastKnownHp.clear();
        }
    }

    private boolean isWhitelisted(NPC npc) {
        String npcName = npc.getName();
        return npcName != null && EXTRA_BOSSES.containsKey(Text.removeTags(npcName).toLowerCase(Locale.ROOT));
    }

    private NPC getNearestBoss() {
        Player player = client.getLocalPlayer();
        if (player == null) {
            return null;
        }

        NPC nearest = null;
        int best = NEARBY_DISTANCE + 1;
        for (NPC npc : nearbyBosses) {
            int distance = npc.getWorldLocation().distanceTo(player.getWorldLocation());
            if (distance < best) {
                best = distance;
                nearest = npc;
            }
        }
        return nearest;
    }

    @Provides
    BetterBossHealthBarConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BetterBossHealthBarConfig.class);
    }
}

package com.betterbosshealthbar;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.TreeSet;

/**
 * Parses the "Boss Name: 75, 50, 25" breakpoint config into a lookup of
 * lowercase boss name to ascending breakpoint fractions (0-1, exclusive).
 */
final class Breakpoints {
    static final float[] NONE = new float[0];

    private Breakpoints() {
    }

    static Map<String, float[]> parse(String config) {
        if (config == null || config.isEmpty()) {
            return Collections.emptyMap();
        }

        Map<String, float[]> result = new HashMap<>();
        for (String rawLine : config.split("\\r?\\n")) {
            String line = rawLine.trim();
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }

            int sep = line.lastIndexOf(':');
            if (sep < 0) {
                sep = line.lastIndexOf('=');
            }
            if (sep <= 0) {
                continue;
            }

            String name = normalizeName(line.substring(0, sep));
            if (name.isEmpty()) {
                continue;
            }

            TreeSet<Float> values = new TreeSet<>();
            for (String token : line.substring(sep + 1).split("[,;\\s]+")) {
                String number = token.replace("%", "").trim();
                if (number.isEmpty()) {
                    continue;
                }
                try {
                    float percent = Float.parseFloat(number);
                    if (percent > 0 && percent < 100) {
                        values.add(percent / 100f);
                    }
                } catch (NumberFormatException ignored) {
                    // skip invalid entries
                }
            }

            if (!values.isEmpty()) {
                float[] fractions = new float[values.size()];
                int i = 0;
                for (float value : values) {
                    fractions[i++] = value;
                }
                result.put(name, fractions);
            }
        }
        return result;
    }

    static String normalizeName(String name) {
        return name.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package com.betterbosshealthbar;

import lombok.Getter;

/**
 * Tracks the true boss health and the animated values drawn by the overlay.
 * All values are fractions of max health, 0-1. Accessed only from the client thread.
 */
class HealthBarState {
    private static final double SNAP_EPSILON = 0.0005;
    // Largest frame step, so a stall does not make the bar jump
    private static final double MAX_FRAME_SECONDS = 0.1;
    private static final double FADE_SECONDS = 1;

    @Getter
    private boolean active;
    @Getter
    private String name = "";
    @Getter
    private int currentHp;
    @Getter
    private int maxHp;

    /**
     * True health fraction reported by the game.
     */
    @Getter
    private double target;
    /**
     * Animated health fraction.
     */
    @Getter
    private double fill;
    /**
     * Animated damage buffer fraction, always >= fill.
     */
    @Getter
    private double buffer;

    @Getter
    private double visibility;

    private int bufferReleaseTick;
    private long flashStartNanos;
    private long lastFrameNanos;

    void reset() {
        active = false;
        name = "";
        currentHp = 0;
        maxHp = 0;
        flashStartNanos = 0;
        lastFrameNanos = 0;
        visibility = 0;
    }

    /**
     * Feed the latest health values from the game. Called every client tick.
     */
    void update(String name, int current, int max, int tick, long nowNanos, int bufferDelayTicks) {
        double fraction = clamp(current / (double) max);

        if (!active || !this.name.equals(name)) {
            // New boss: start from its current health without animating
            active = true;
            this.name = name;
            target = fill = buffer = fraction;
            flashStartNanos = 0;
            bufferReleaseTick = tick;
        } else if (current != currentHp || max != maxHp) {
            if (fraction < target) {
                flashStartNanos = nowNanos;
                bufferReleaseTick = tick + bufferDelayTicks;
            }
            target = fraction;
        }

        currentHp = current;
        maxHp = max;
    }

    /**
     * Step the animation. Called once per rendered frame.
     */
    void animate(long nowNanos, int tick, int fillSpeed, int bufferSpeed, int bufferDelayTicks) {
        double dt = lastFrameNanos == 0 ? 0 : Math.min((nowNanos - lastFrameNanos) / 1e9, MAX_FRAME_SECONDS);
        lastFrameNanos = nowNanos;

        fill = approach(fill, target, fillSpeed, dt);

        if (bufferDelayTicks <= 0 || buffer < fill) {
            buffer = fill;
        } else if (tick >= bufferReleaseTick) {
            buffer = approach(buffer, fill, bufferSpeed, dt);
        }

        // Handles health bar fading in and out on encounter start / end.
        double step = dt / FADE_SECONDS;
        visibility = active ? Math.min(1, visibility + step) : Math.max(0, visibility - step);
    }

    /**
     * @return flash strength from 1 (just hit) fading to 0
     */
    float flashAlpha(long nowNanos, int durationMs) {
        if (durationMs <= 0 || flashStartNanos == 0) {
            return 0f;
        }

        double t = (nowNanos - flashStartNanos) / 1e6 / durationMs;
        if (t >= 1) {
            flashStartNanos = 0;
            return 0f;
        }
        double remaining = 1 - t;
        return (float) (remaining * remaining);
    }

    /**
     * Exponential ease toward the target. Speed 0 snaps instantly.
     */
    private static double approach(double value, double target, int speed, double dt) {
        if (speed <= 0 || Math.abs(target - value) < SNAP_EPSILON) {
            return target;
        }
        return value + (target - value) * (1 - Math.exp(-speed * dt));
    }

    private static double clamp(double value) {
        return Math.max(0, Math.min(1, value));
    }

    // Helper function that keeps a buffer persistent for preview purposes.
    void previewBuffer() {
     buffer = 0.6;
    }

    void deactivate()
    {
        active = false;
    }

    boolean isVisible()
    {
        return visibility > 0;
    }
}

